			dw kw_vtov, var_hot_control_control, tmp1
			dw kw_cpeqvl, tmp1, 0
			dw kw_ftov, tmp1
			dw kw_andvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if8_e
			dw p_keyin_c, var_k
if10_1:

			; Main.bas 93: End If
if9_1:

			; Main.bas 94: ElseIf Running() = 0 Then
			dw if8_e_go
if8_2:
			dw p_running_c
			dw kw_vtov, var_running_running, tmp0
			dw kw_cpeqvl, tmp0, 0
			dw kw_goto_iffalse_n, if8_3

